def get_case_tokens_until_end(tokens):
    """Get tokens until the matching END for a CASE statement, handling nested CASE/END pairs."""
    argument_tokens = []

    next_token = next(tokens, None)
    case_count = 1  # We start with one CASE already encountered

    while next_token is not None and case_count > 0:
        argument_tokens.append(next_token)

        # Check for nested CASE statements
        if next_token.lower() == "case":
            case_count += 1
        # Check for END statements
        elif next_token.lower() == "end":
            case_count -= 1

        if case_count > 0:  # Only get next token if we haven't matched all CASE/END pairs
            next_token = next(tokens, None)
        else:
            # We've matched the outermost CASE, so the last token should be "end"
            # Remove the final "end" from argument_tokens since it belongs to the outer CASE
            if argument_tokens and argument_tokens[-1].lower() == "end":
                argument_tokens.pop()
            break

    return argument_tokens, next_token


def get_case_tokens_until_keyword(tokens, stop_words):
    """Get tokens until the specified keyword, handling nested CASE/END pairs."""
    argument_tokens = []

    next_token = next(tokens, None)
    case_count = 0

    while next_token is not None and not (
        next_token.lower() in stop_words and case_count <= 0
    ):
        argument_tokens.append(next_token)

        # Check for nested CASE statements
        if next_token.lower() == "case":
            case_count += 1
        # Check for END statements
        elif next_token.lower() == "end":
            case_count -= 1

        next_token = next(tokens, None)

    return argument_tokens, next_token


def get_case_tokens_until_keywords(tokens, stop_words):
    """Get tokens until any of the specified keywords, handling nested CASE/END pairs."""
    return get_case_tokens_until_keyword(tokens, stop_words)


def get_case_tokens_until_end_or_none(tokens):
    """Get tokens until END or None, handling nested CASE/END pairs."""
    argument_tokens = []

    next_token = next(tokens, None)
    case_count = 0

    while next_token is not None and not (
        (next_token is None or next_token.lower() == "end") and case_count <= 0
    ):
        argument_tokens.append(next_token)

        # Check for nested CASE statements
        if next_token.lower() == "case":
            case_count += 1
        # Check for END statements
        elif next_token.lower() == "end":
            case_count -= 1

        next_token = next(tokens, None)

    return argument_tokens, next_token
